//! The Rust half of the split: the CLI's call into the Lean extraction core.
//!
//! Everything that parses a container or decodes a resource lives in
//! `lean/src/MmfExtract/` and is reached through one function,
//! `mmf_extract(request) -> report`. The C ABI for it is generated by
//! `build.rs` from the library that was actually built, so the symbol names
//! cannot drift from the Lean side; the rest of this module is the request, the
//! report, and the report's translation back into the CLI's numbers.
//!
//! The request and the report are both line-oriented text, so neither side has
//! to know the other's types:

//! ```text
//! asset_dir\t/RawAssets
//! output\t/workspace/extracted
//! types\tpictures,sounds
//! original\t0
//! raw\t0
//! ```

//! The report is what the CLI used to fill in itself, one `key\tvalue` line
//! plus one `fail\t…` line per failure.

use anyhow::{bail, Context, Result};
use std::path::Path;

include!(concat!(env!("OUT_DIR"), "/lean_core.rs"));

/// What the Rust CLI asks the Lean core for.
pub struct Request {
    pub asset_dir: std::path::PathBuf,
    pub output: std::path::PathBuf,
    /// `["all"]` or a comma-separated list of asset type names.
    pub types: Vec<String>,
    pub original: bool,
    pub raw: bool,
}

impl Request {
    /// The text the Lean core parses.
    pub fn render(&self) -> Result<std::ffi::CString> {
        let types = self.types.join(",");
        let text = format!(
            "asset_dir\t{}\noutput\t{}\ntypes\t{}\noriginal\t{}\nraw\t{}\n",
            self.asset_dir.display(),
            self.output.display(),
            if types.is_empty() { "all" } else { &types },
            u8::from(self.original),
            u8::from(self.raw),
        );
        std::ffi::CString::new(text).context("the request holds a NUL byte")
    }
}

/// What one extraction run wrote and what failed.
#[derive(Debug, Default)]
pub struct Report {
    pub pictures: usize,
    pub sounds: usize,
    pub films: usize,
    pub scripts: usize,
    pub blobs: usize,
    pub models: usize,
    pub total: usize,
    pub failed: Vec<String>,
}

/// The Lean object header, as `lean.h` declares it: `m_rc`, `m_cs_sz`,
/// `m_other` and then `m_tag` in the top byte of the first eight.
///
/// Only two things are read out of a Lean object here: the tag of an
/// `io_result` (which is what the module initializer returns) and the payload
/// of a `String`. Both layouts are public and stable -- `lean_io_result_is_error`
/// and `lean_string_cstr` are static inline functions in `lean.h` built on
/// exactly these fields -- but they are not exported by `libleanshared.so`, so
/// they are spelled out here instead of declared there.
fn lean_tag(object: *mut std::ffi::c_void) -> u8 {
    // `m_tag` is the eighth byte of the header.
    unsafe { (*(object as *const u64) >> 56) as u8 }
}

/// Whether an `IO.Result` is its `error` constructor, which has tag 1.
fn io_result_is_error(result: *mut std::ffi::c_void) -> bool {
    lean_tag(result) == 1
}

/// A Lean `String` object: the header, then `m_size` (the byte length
/// *including* the NUL terminator), `m_capacity`, `m_length`, then the bytes.
#[repr(C)]
struct LeanString {
    header: u64,
    size: usize,
    capacity: usize,
    length: usize,
}

/// The bytes of the `String` a Lean call returned.
fn lean_string(object: *mut std::ffi::c_void) -> Result<String> {
    let bytes = unsafe {
        let string = &*(object as *const LeanString);
        if string.size < 1 {
            bail!("the Lean extraction core returned a string with no payload");
        }
        std::slice::from_raw_parts(
            (object as *const u8).add(std::mem::size_of::<LeanString>()),
            // `m_size` counts the NUL terminator the runtime appends.
            string.size - 1,
        )
    };
    std::str::from_utf8(bytes)
        .context("the report is not valid UTF-8")
        .map(str::to_owned)
}

/// Run the Lean extraction core once.
///
/// The Lean runtime is initialised on the first call and left in place: a long
/// program may extract more than one asset folder, and re-initialising it is
/// both unnecessary and unsupported.
///
/// The calls are serialised by a lock. `unsafeIO` runs the Lean action
/// immediately on the calling thread, and the Lean runtime is not prepared for
/// that from two threads at once — with the test suite's default parallelism
/// the process aborts inside the runtime. The CLI is single-threaded anyway, so
/// the lock costs it nothing.
pub fn run(request: &Request) -> Result<Report> {
    static INIT: std::sync::Once = std::sync::Once::new();
    static LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
    INIT.call_once(|| unsafe {
        lean_initialize_runtime_module();
        let initialised = initialize_lean_core();
        if io_result_is_error(initialised) {
            lean_io_result_show_error(initialised);
            panic!("the Lean extraction core could not be initialised");
        }
    });
    let _serialised = LOCK.lock().unwrap_or_else(|poisoned| poisoned.into_inner());

    let c_request = request.render()?;
    let reply = unsafe {
        let argument = lean_mk_string(c_request.as_ptr());
        if argument.is_null() {
            bail!("the Lean runtime could not build the request string");
        }
        let result = mmf_extract(argument);
        if result.is_null() {
            bail!("the Lean extraction core returned nothing");
        }
        lean_string(result)?
    };

    parse_report(&reply).context("parsing the Lean core's report")
}

/// Write the 3D game's index page through the Lean core.
///
/// The page is HTML the Lean core writes, and it is called after the Rust
/// converter in the modern modes because the converter is the half that adds the
/// glTFs the page lists. In `--original` the Lean core writes the page itself at
/// the end of its run, so this is not called; either way the page has exactly
/// one writer in one language.
///
/// Returns the number of figures the page lists.
pub fn write_3d_index(base: &Path, texture_dir: &Path, model_dir: &Path) -> Result<usize> {
    static INIT: std::sync::Once = std::sync::Once::new();
    static LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
    INIT.call_once(|| unsafe {
        lean_initialize_runtime_module();
        let initialised = initialize_lean_core();
        if io_result_is_error(initialised) {
            lean_io_result_show_error(initialised);
            panic!("the Lean extraction core could not be initialised");
        }
    });
    let _serialised = LOCK.lock().unwrap_or_else(|poisoned| poisoned.into_inner());

    let text = format!(
        "base\t{}\ntexture_dir\t{}\nmodel_dir\t{}\n",
        base.display(),
        texture_dir.display(),
        model_dir.display(),
    );
    let request = std::ffi::CString::new(text).context("the index request holds a NUL byte")?;
    let reply = unsafe {
        let argument = lean_mk_string(request.as_ptr());
        if argument.is_null() {
            bail!("the Lean runtime could not build the index request string");
        }
        let result = mmf_index(argument);
        if result.is_null() {
            bail!("the Lean extraction core returned nothing");
        }
        lean_string(result)?
    };
    let (key, value) = reply.split_once('\t').unwrap_or((reply.as_str(), ""));
    match key.trim_end() {
        "ok" => value.trim_end().parse().with_context(|| {
            format!("the index page's figure count ('{value}') is not a number")
        }),
        "error" => bail!("writing the 3D index page: {value}"),
        other => bail!("unknown index reply '{other}'"),
    }
}

/// Turn the report text back into the numbers and the failure list.
fn parse_report(text: &str) -> Result<Report> {
    let mut report = Report::default();
    for row in text.lines() {
        let (key, value) = row.split_once('\t').unwrap_or((row, ""));
        match key {
            "pictures" => report.pictures = parse_count(value, "pictures")?,
            "sounds" => report.sounds = parse_count(value, "sounds")?,
            "films" => report.films = parse_count(value, "films")?,
            "scripts" => report.scripts = parse_count(value, "scripts")?,
            "blobs" => report.blobs = parse_count(value, "blobs")?,
            "models" => report.models = parse_count(value, "models")?,
            "total" => report.total = parse_count(value, "total")?,
            "failed" => report.failed = Vec::new(),
            "fail" => report.failed.push(value.to_string()),
            "error" => bail!("the Lean extraction core failed: {value}"),
            other => bail!("unknown report line '{other}'"),
        }
    }
    Ok(report)
}

fn parse_count(value: &str, key: &str) -> Result<usize> {
    value
        .parse()
        .with_context(|| format!("the report's {key} count ('{value}') is not a number"))
}
